"use client";

/**
 * Phone mockup: a phone tilts up out of the floor of the frame and settles at a
 * gentle angle, showing a screenshot, a screen recording or a placeholder app.
 *
 * Written by Better Design. Painted from the theme prop; with no picture the
 * screen shows a placeholder app drawn from the same tokens.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, Img, interpolate, OffthreadVideo, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, PhoneFrame, pickFont, progress, springs, type VideoTheme, useVideoTheme, withAlpha, srcOf } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "700"], subsets: ["latin"] });

/** Rendered width of the phone case, in pixels. */
const PHONE_W = 420;
const VIDEO = /\.(mp4|webm|mov)(\?.*)?$/i;

export interface PhoneMockupProps {
  /** Image or video for the screen. A path ending in .mp4, .webm or .mov plays as video. */
  src?: string;
  /** Resting yaw of the phone in degrees. 0 faces the camera. */
  tilt?: number;
  /** One line beside the phone. Leave empty to centre the phone alone. */
  caption?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

function PlaceholderApp({ theme, frame }: { theme: VideoTheme; frame: number }) {
  const bar = (w: string, h: number, c = withAlpha(theme.foreground, 0.12)) => <div style={{ width: w, height: h, borderRadius: h / 2, background: c }} />;
  const fill = easings.out(progress(frame, 34, 40));
  return (
    <div style={{ position: "absolute", inset: 0, background: theme.background, padding: "70px 26px 0", display: "flex", flexDirection: "column", gap: 22 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        {bar("44%", 22, withAlpha(theme.foreground, 0.85))}
        <div style={{ width: 42, height: 42, borderRadius: 21, background: theme.muted, border: `1px solid ${theme.border}` }} />
      </div>
      <div style={{ borderRadius: 26, padding: 24, background: theme.card, border: `1px solid ${theme.border}`, display: "flex", flexDirection: "column", gap: 16 }}>
        {bar("40%", 12)}
        {bar("62%", 30, withAlpha(theme.foreground, 0.8))}
        <div style={{ height: 10, borderRadius: 5, background: theme.muted, marginTop: 6 }}>
          <div style={{ width: `${fill * 72}%`, height: "100%", borderRadius: 5, background: theme.primary }} />
        </div>
      </div>
      {[0.68, 0.52, 0.6].map((w, i) => (
        <div key={i} style={{ display: "flex", alignItems: "center", gap: 16, padding: 16, borderRadius: 20, background: theme.card, border: `1px solid ${theme.border}` }}>
          <div style={{ width: 46, height: 46, borderRadius: 14, background: i === 0 ? withAlpha(theme.primary, 0.2) : theme.muted }} />
          <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 9 }}>
            {bar(`${w * 100}%`, 13, withAlpha(theme.foreground, 0.7))}
            {bar(`${w * 60}%`, 10)}
          </div>
        </div>
      ))}
      <div style={{ position: "absolute", left: 26, right: 26, bottom: 36, height: 64, borderRadius: 32, background: theme.primary, display: "flex", alignItems: "center", justifyContent: "center" }}>
        {bar("34%", 14, withAlpha(theme.primaryForeground, 0.9))}
      </div>
    </div>
  );
}

/** A phone that tilts up into view and settles, with a screen from `src` or a drawn app. */
export function PhoneMockup({
  src,
  tilt = 10,
  caption = "Your product, in their pocket",
  theme: themeOverride,
  font,
}: PhoneMockupProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);

  const rise = spring({ frame: frame - 4, fps, config: springs.soft });
  const pitch = interpolate(rise, [0, 1], [58, 6]);
  const yaw = interpolate(rise, [0, 1], [-tilt * 2.2, -tilt]);
  const lift = interpolate(rise, [0, 1], [760, 0]);
  const enter = interpolate(frame, [4, 16], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const glare = interpolate(frame, [4, 60], [-40, 120], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const captionT = easings.out(progress(frame, 26, 22));
  const hasCaption = Boolean(caption);

  const screen = src ? (
    VIDEO.test(src) ? (
      <OffthreadVideo src={srcOf(src)} muted style={{ width: "100%", height: "100%", objectFit: "cover" }} />
    ) : (
      <Img src={srcOf(src)} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
    )
  ) : (
    <PlaceholderApp theme={theme} frame={frame} />
  );

  return (
    <AbsoluteFill
      style={{
        background: `radial-gradient(ellipse 60% 70% at ${hasCaption ? 66 : 50}% 55%, ${withAlpha(theme.primary, 0.1)}, ${theme.background} 70%), ${theme.background}`,
        fontFamily: family,
        flexDirection: "row",
        alignItems: "center",
        justifyContent: "center",
        gap: 180,
      }}
    >
      {hasCaption ? (
        <div style={{ width: 640, opacity: captionT, transform: `translateY(${(1 - captionT) * 20}px)` }}>
          <div style={{ width: 56, height: 6, borderRadius: 3, background: theme.primary, marginBottom: 36 }} />
          <div style={{ fontSize: 76, fontWeight: 700, lineHeight: 1.05, letterSpacing: "-0.035em", color: theme.foreground }}>{caption}</div>
        </div>
      ) : null}
      <div style={{ perspective: 2200, opacity: enter }}>
        <div
          style={{
            transform: `translateY(${lift}px) rotateX(${pitch}deg) rotateY(${yaw}deg)`,
            transformOrigin: "50% 100%",
            filter: "drop-shadow(0 60px 60px oklch(0 0 0 / 0.22)) drop-shadow(0 18px 22px oklch(0 0 0 / 0.14))",
          }}
        >
          <PhoneFrame
            width={PHONE_W}
            overlay={
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  background: `linear-gradient(115deg, oklch(1 0 0 / 0) ${glare}%, oklch(1 0 0 / 0.1) ${glare + 10}%, oklch(1 0 0 / 0) ${glare + 26}%)`,
                }}
              />
            }
          >
            {screen}
          </PhoneFrame>
        </div>
      </div>
    </AbsoluteFill>
  );
}
